from flask import current_app, g, jsonify, request, url_for

from .. import db
from ..models import Follow, Permission, Post, User
from . import api
from .decorators import permission_required
from .errors import bad_request


def _paginate(query, endpoint, per_page_default, **kwargs):
    page = request.args.get('page', 1, type=int)
    per_page = min(
        request.args.get('per_page', per_page_default, type=int),
        100,
    )
    pagination = query.paginate(page, per_page=per_page, error_out=False)
    prev_url = None
    if pagination.has_prev:
        prev_url = url_for(
            endpoint,
            page=page - 1,
            per_page=per_page,
            _external=True,
            **kwargs
        )
    next_url = None
    if pagination.has_next:
        next_url = url_for(
            endpoint,
            page=page + 1,
            per_page=per_page,
            _external=True,
            **kwargs
        )
    return pagination, prev_url, next_url


@api.route('/users/<int:id>')
def get_user(id):
    user = User.query.get_or_404(id)
    return jsonify(user.to_json())


@api.route('/users/<int:id>/posts/')
def get_user_posts(id):
    user = User.query.get_or_404(id)
    pagination, prev_url, next_url = _paginate(
        user.posts.order_by(Post.timestamp.desc()),
        'api.get_user_posts',
        current_app.config['FLASKY_POSTS_PER_PAGE'],
        id=id
    )
    posts = pagination.items
    return jsonify({
        'posts': [post.to_json() for post in posts],
        'prev': prev_url,
        'next': next_url,
        'count': pagination.total,
    })


@api.route('/users/<int:id>/timeline/')
def get_user_followed_posts(id):
    user = User.query.get_or_404(id)
    pagination, prev_url, next_url = _paginate(
        user.followed_posts.order_by(Post.timestamp.desc()),
        'api.get_user_followed_posts',
        current_app.config['FLASKY_POSTS_PER_PAGE'],
        id=id
    )
    posts = pagination.items
    return jsonify({
        'posts': [post.to_json() for post in posts],
        'prev': prev_url,
        'next': next_url,
        'count': pagination.total,
    })


@api.route('/users/<int:id>/followers/')
def get_user_followers(id):
    user = User.query.get_or_404(id)
    pagination, prev_url, next_url = _paginate(
        user.followers.filter(Follow.follower_id != user.id).order_by(
            Follow.timestamp.desc()),
        'api.get_user_followers',
        current_app.config['FLASKY_FOLLOWERS_PER_PAGE'],
        id=id
    )
    return jsonify({
        'followers': [follow.follower.to_json() for follow in pagination.items],
        'prev': prev_url,
        'next': next_url,
        'count': pagination.total,
    })


@api.route('/users/<int:id>/followed/')
def get_user_followed(id):
    user = User.query.get_or_404(id)
    pagination, prev_url, next_url = _paginate(
        user.followed.filter(Follow.followed_id != user.id).order_by(
            Follow.timestamp.desc()),
        'api.get_user_followed',
        current_app.config['FLASKY_FOLLOWERS_PER_PAGE'],
        id=id
    )
    return jsonify({
        'followed': [follow.followed.to_json() for follow in pagination.items],
        'prev': prev_url,
        'next': next_url,
        'count': pagination.total,
    })


@api.route('/users/<int:id>/relationship/')
def get_user_relationship(id):
    user = User.query.get_or_404(id)
    return jsonify({
        'user_id': user.id,
        'follows': g.current_user.is_following(user),
        'followed_by': g.current_user.is_followed_by(user),
    })


@api.route('/users/<int:id>/follow/', methods=['POST'])
@permission_required(Permission.FOLLOW)
def follow_user(id):
    user = User.query.get_or_404(id)
    if user == g.current_user:
        return bad_request('Cannot follow yourself')
    if g.current_user.is_following(user):
        return jsonify(user.to_json())
    g.current_user.follow(user)
    db.session.commit()
    return jsonify(user.to_json()), 201


@api.route('/users/<int:id>/follow/', methods=['DELETE'])
@permission_required(Permission.FOLLOW)
def unfollow_user(id):
    user = User.query.get_or_404(id)
    if user == g.current_user:
        return bad_request('Cannot unfollow yourself')
    if not g.current_user.is_following(user):
        return bad_request('You are not following this user')
    g.current_user.unfollow(user)
    db.session.commit()
    return '', 204

