import hashlib
from datetime import datetime

import bleach
from flask import current_app, request, url_for
from flask_login import AnonymousUserMixin, UserMixin
from itsdangerous import (BadData, BadSignature, SignatureExpired,
                          TimedJSONWebSignatureSerializer as Serializer)
from markdown import markdown
from sqlalchemy import event
from werkzeug.security import check_password_hash, generate_password_hash

from . import db, login_manager
from .exceptions import ValidationError


def _datetime_to_iso(value):
    if value is None:
        return None
    return value.isoformat() + 'Z'


def _url_for(endpoint, **values):
    external = values.pop('_external', True)
    try:
        return url_for(endpoint, _external=external, **values)
    except RuntimeError:
        return url_for(endpoint, _external=False, **values)


class Permission(object):
    FOLLOW = 1
    COMMENT = 2
    WRITE = 4
    MODERATE = 8
    ADMIN = 16


class Role(db.Model):
    __tablename__ = 'roles'
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(64), unique=True)
    default = db.Column(db.Boolean, default=False, index=True)
    permissions = db.Column(db.Integer)
    users = db.relationship('User', backref='role', lazy='dynamic')

    def __init__(self, **kwargs):
        super(Role, self).__init__(**kwargs)
        if self.permissions is None:
            self.permissions = 0

    @staticmethod
    def insert_roles():
        roles = {
            'User': (
                Permission.FOLLOW |
                Permission.COMMENT |
                Permission.WRITE, True),
            'Moderator': (
                Permission.FOLLOW |
                Permission.COMMENT |
                Permission.WRITE |
                Permission.MODERATE, False),
            'Administrator': (
                Permission.FOLLOW |
                Permission.COMMENT |
                Permission.WRITE |
                Permission.MODERATE |
                Permission.ADMIN, False),
        }
        for name, (permissions, default) in roles.items():
            role = Role.query.filter_by(name=name).first()
            if role is None:
                role = Role(name=name)
            role.reset_permissions()
            for permission in (
                Permission.FOLLOW,
                Permission.COMMENT,
                Permission.WRITE,
                Permission.MODERATE,
                Permission.ADMIN,
            ):
                if permissions & permission:
                    role.add_permission(permission)
            role.default = default
            db.session.add(role)
        db.session.commit()

    def add_permission(self, perm):
        if not self.has_permission(perm):
            self.permissions += perm

    def remove_permission(self, perm):
        if self.has_permission(perm):
            self.permissions -= perm

    def reset_permissions(self):
        self.permissions = 0

    def has_permission(self, perm):
        return self.permissions is not None and (
            self.permissions & perm) == perm

    def __repr__(self):
        return '<Role %r>' % self.name


class Follow(db.Model):
    __tablename__ = 'follows'
    follower_id = db.Column(
        db.Integer, db.ForeignKey('users.id'), primary_key=True)
    followed_id = db.Column(
        db.Integer, db.ForeignKey('users.id'), primary_key=True)
    timestamp = db.Column(db.DateTime, default=datetime.utcnow, index=True)


class User(UserMixin, db.Model):
    __tablename__ = 'users'
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(64), unique=True, index=True)
    username = db.Column(db.String(64), unique=True, index=True)
    role_id = db.Column(db.Integer, db.ForeignKey('roles.id'))
    password_hash = db.Column(db.String(128))
    confirmed = db.Column(db.Boolean, default=False)
    name = db.Column(db.String(64))
    location = db.Column(db.String(64))
    about_me = db.Column(db.Text())
    member_since = db.Column(db.DateTime(), default=datetime.utcnow)
    last_seen = db.Column(db.DateTime(), default=datetime.utcnow)
    avatar_hash = db.Column(db.String(32))
    posts = db.relationship('Post', backref='author', lazy='dynamic')
    followed = db.relationship(
        'Follow',
        foreign_keys=[Follow.follower_id],
        backref=db.backref('follower', lazy='joined'),
        lazy='dynamic',
        cascade='all, delete-orphan',
    )
    followers = db.relationship(
        'Follow',
        foreign_keys=[Follow.followed_id],
        backref=db.backref('followed', lazy='joined'),
        lazy='dynamic',
        cascade='all, delete-orphan',
    )
    comments = db.relationship('Comment', backref='author', lazy='dynamic')

    @staticmethod
    def add_self_follows():
        for user in User.query.all():
            if not user.is_following(user):
                db.session.add(Follow(follower=user, followed=user))
        db.session.commit()

    @staticmethod
    def _create_self_follow(mapper, connection, target):
        follows = Follow.__table__
        exists = connection.execute(
            follows.select().where(
                (follows.c.follower_id == target.id) &
                (follows.c.followed_id == target.id)
            )
        ).fetchone()
        if exists is None:
            connection.execute(
                follows.insert().values(
                    follower_id=target.id,
                    followed_id=target.id,
                    timestamp=datetime.utcnow(),
                )
            )

    def __init__(self, **kwargs):
        raw_password = kwargs.pop('password', None)
        super(User, self).__init__(**kwargs)
        if self.email is not None:
            self.email = self.email.lower()
        if self.role is None:
            try:
                admin_email = current_app.config.get('FLASKY_ADMIN')
            except RuntimeError:
                admin_email = None
            if admin_email and self.email == admin_email:
                self.role = Role.query.filter_by(name='Administrator').first()
            if self.role is None:
                self.role = Role.query.filter_by(default=True).first()
        if self.email is not None and self.avatar_hash is None:
            self.avatar_hash = self.gravatar_hash()
        if raw_password:
            self.password = raw_password

    @property
    def password(self):
        raise AttributeError('password is not a readable attribute')

    @password.setter
    def password(self, password):
        self.password_hash = generate_password_hash(password)

    def verify_password(self, password):
        if self.password_hash is None:
            return False
        return check_password_hash(self.password_hash, password)

    def generate_confirmation_token(self, expiration=3600):
        s = Serializer(
            current_app.config['SECRET_KEY'],
            expires_in=expiration,
        )
        return s.dumps({'confirm': self.id}).decode('utf-8')

    def confirm(self, token):
        s = Serializer(current_app.config['SECRET_KEY'])
        try:
            data = s.loads(token.encode('utf-8'))
        except (BadSignature, SignatureExpired, BadData):
            return False
        if data.get('confirm') != self.id:
            return False
        self.confirmed = True
        db.session.add(self)
        return True

    def generate_reset_token(self, expiration=3600):
        s = Serializer(
            current_app.config['SECRET_KEY'],
            expires_in=expiration,
        )
        return s.dumps({'reset': self.id}).decode('utf-8')

    @staticmethod
    def reset_password(token, new_password):
        s = Serializer(current_app.config['SECRET_KEY'])
        try:
            data = s.loads(token.encode('utf-8'))
        except (BadSignature, SignatureExpired, BadData):
            return False
        user = User.query.get(data.get('reset'))
        if user is None:
            return False
        user.password = new_password
        db.session.add(user)
        return True

    def generate_email_change_token(self, new_email, expiration=3600):
        s = Serializer(
            current_app.config['SECRET_KEY'],
            expires_in=expiration,
        )
        return s.dumps(
            {'change_email': self.id, 'new_email': new_email.lower()}
        ).decode('utf-8')

    def change_email(self, token):
        s = Serializer(current_app.config['SECRET_KEY'])
        try:
            data = s.loads(token.encode('utf-8'))
        except (BadSignature, SignatureExpired, BadData):
            return False
        if data.get('change_email') != self.id:
            return False
        new_email = data.get('new_email')
        if new_email is None:
            return False
        new_email = new_email.lower()
        if new_email == self.email:
            return False
        if User.query.filter_by(email=new_email).first() is not None:
            return False
        self.email = new_email
        self.avatar_hash = self.gravatar_hash()
        db.session.add(self)
        return True

    def can(self, perm):
        return self.role is not None and self.role.has_permission(perm)

    def is_administrator(self):
        return self.can(Permission.ADMIN)

    def ping(self):
        self.last_seen = datetime.utcnow()
        db.session.add(self)

    def gravatar_hash(self):
        if self.email is None:
            return ''
        return hashlib.md5(self.email.lower().encode('utf-8')).hexdigest()

    def gravatar(self, size=100, default='identicon', rating='g'):
        try:
            secure = request.is_secure
        except RuntimeError:
            secure = True
        url = 'https://secure.gravatar.com/avatar'
        if not secure:
            url = 'http://www.gravatar.com/avatar'
        hash_value = self.avatar_hash or self.gravatar_hash()
        return '%s/%s?s=%d&d=%s&r=%s' % (
            url, hash_value, size, default, rating)

    def follow(self, user):
        if user is None or user.id is None or self.id is None:
            return None
        if not self.is_following(user):
            f = Follow(follower=self, followed=user)
            db.session.add(f)
            return f
        return None

    def unfollow(self, user):
        if user is None or user.id is None or self.id is None:
            return None
        f = self.followed.filter_by(followed_id=user.id).first()
        if f:
            db.session.delete(f)
            return f
        return None

    def is_following(self, user):
        if user is None:
            return False
        if self.id is None or user.id is None:
            return self is user
        return self.followed.filter_by(followed_id=user.id).first() is not None

    def is_followed_by(self, user):
        if user is None:
            return False
        if self.id is None or user.id is None:
            return self is user
        return self.followers.filter_by(
            follower_id=user.id).first() is not None

    @property
    def followed_posts(self):
        followed = Post.query.join(
            Follow, Follow.followed_id == Post.author_id
        ).filter(Follow.follower_id == self.id)
        own = Post.query.filter_by(author_id=self.id)
        return followed.union(own)

    def to_json(self):
        return {
            'url': _url_for('api.get_user', id=self.id),
            'username': self.username,
            'email': self.email,
            'confirmed': self.confirmed,
            'name': self.name,
            'location': self.location,
            'about_me': self.about_me,
            'member_since': _datetime_to_iso(self.member_since),
            'last_seen': _datetime_to_iso(self.last_seen),
            'posts_url': _url_for('api.get_user_posts', id=self.id),
            'followed_posts_url': _url_for(
                'api.get_user_followed_posts', id=self.id),
            'post_count': self.posts.count(),
            'follower_count': max(self.followers.count() - 1, 0),
            'followed_count': max(self.followed.count() - 1, 0),
            'avatar': self.gravatar(),
        }

    def generate_auth_token(self, expiration):
        s = Serializer(
            current_app.config['SECRET_KEY'],
            expires_in=expiration,
        )
        return s.dumps({'id': self.id}).decode('utf-8')

    @staticmethod
    def verify_auth_token(token):
        s = Serializer(current_app.config['SECRET_KEY'])
        try:
            data = s.loads(token.encode('utf-8'))
        except (BadSignature, SignatureExpired, BadData):
            return None
        return User.query.get(data.get('id'))

    def __repr__(self):
        return '<User %r>' % self.username


class AnonymousUser(AnonymousUserMixin):
    def can(self, permissions):
        return False

    def is_administrator(self):
        return False


login_manager.anonymous_user = AnonymousUser


@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))


class Post(db.Model):
    __tablename__ = 'posts'
    id = db.Column(db.Integer, primary_key=True)
    body = db.Column(db.Text)
    body_html = db.Column(db.Text)
    category = db.Column(db.String(64), default='general', index=True)
    timestamp = db.Column(db.DateTime, index=True, default=datetime.utcnow)
    author_id = db.Column(db.Integer, db.ForeignKey('users.id'))
    comments = db.relationship(
        'Comment',
        backref='post',
        lazy='dynamic',
        cascade='all, delete-orphan',
    )

    @staticmethod
    def on_changed_body(target, value, oldvalue, initiator):
        allowed_tags = [
            'a', 'abbr', 'acronym', 'b', 'blockquote', 'code', 'em', 'i',
            'li', 'ol', 'pre', 'strong', 'ul', 'h1', 'h2', 'h3', 'p',
        ]
        html = markdown(value or '', output_format='html')
        cleaned = bleach.clean(html, tags=allowed_tags, strip=True)
        target.body_html = bleach.linkify(cleaned)

    def to_json(self):
        return {
            'url': _url_for('api.get_post', id=self.id),
            'body': self.body,
            'body_html': self.body_html,
            'timestamp': _datetime_to_iso(self.timestamp),
            'author_url': _url_for('api.get_user', id=self.author_id),
            'comments_url': _url_for('api.get_post_comments', id=self.id),
            'comment_count': self.comments.count(),
            'category': self.category,
        }

    @staticmethod
    def from_json(json_post):
        body = None if json_post is None else json_post.get('body')
        if body is None or not body.strip():
            raise ValidationError('post does not have a body')
        category = (json_post.get('category') or 'general').strip() or 'general'
        return Post(body=body, category=category)

    def __repr__(self):
        return '<Post %r>' % self.id


class Comment(db.Model):
    __tablename__ = 'comments'
    id = db.Column(db.Integer, primary_key=True)
    body = db.Column(db.Text)
    body_html = db.Column(db.Text)
    timestamp = db.Column(db.DateTime, index=True, default=datetime.utcnow)
    disabled = db.Column(db.Boolean, default=False)
    author_id = db.Column(db.Integer, db.ForeignKey('users.id'))
    post_id = db.Column(db.Integer, db.ForeignKey('posts.id'))

    @staticmethod
    def on_changed_body(target, value, oldvalue, initiator):
        allowed_tags = [
            'a', 'abbr', 'acronym', 'b', 'blockquote', 'code', 'em', 'i',
            'li', 'ol', 'pre', 'strong', 'ul', 'h1', 'h2', 'h3', 'p',
        ]
        html = markdown(value or '', output_format='html')
        cleaned = bleach.clean(html, tags=allowed_tags, strip=True)
        target.body_html = bleach.linkify(cleaned)

    def to_json(self):
        return {
            'url': _url_for('api.get_comment', id=self.id),
            'post_url': _url_for('api.get_post', id=self.post_id),
            'author_url': _url_for('api.get_user', id=self.author_id),
            'body': self.body,
            'body_html': self.body_html,
            'timestamp': _datetime_to_iso(self.timestamp),
            'disabled': bool(self.disabled),
        }

    @staticmethod
    def from_json(json_comment):
        body = None if json_comment is None else json_comment.get('body')
        if body is None or not body.strip():
            raise ValidationError('comment does not have a body')
        return Comment(body=body)

    def __repr__(self):
        return '<Comment %r>' % self.id


event.listen(Post.body, 'set', Post.on_changed_body)
event.listen(Comment.body, 'set', Comment.on_changed_body)
event.listen(User, 'after_insert', User._create_self_follow)


