from flask import current_app, g, jsonify, request, url_for
from sqlalchemy import or_

from .. import db
from ..models import Permission, Post
from . import api
from .decorators import permission_required
from .errors import forbidden


def _paginate_posts(query, endpoint, **kwargs):
    page = request.args.get('page', 1, type=int)
    per_page = min(
        request.args.get(
            'per_page',
            current_app.config['FLASKY_POSTS_PER_PAGE'],
            type=int,
        ),
        100,
    )
    pagination = query.paginate(page, per_page=per_page, error_out=False)
    prev_url = None
    if pagination.has_prev:
        prev_url = url_for(
            endpoint, page=page - 1, per_page=per_page, _external=True, **kwargs)
    next_url = None
    if pagination.has_next:
        next_url = url_for(
            endpoint, page=page + 1, per_page=per_page, _external=True, **kwargs)
    return pagination, prev_url, next_url


@api.route('/posts/')
def get_posts():
    query = Post.query
    q = request.args.get('q', '').strip()
    category = request.args.get('category', '').strip()
    if q:
        query = query.filter(
            or_(Post.body.ilike('%%%s%%' % q), Post.body_html.ilike('%%%s%%' % q))
        )
    if category:
        query = query.filter(Post.category == category)
    pagination, prev_url, next_url = _paginate_posts(
        query.order_by(Post.timestamp.desc()),
        'api.get_posts',
    )
    posts = pagination.items
    return jsonify({
        'posts': [post.to_json() for post in posts],
        'prev': prev_url,
        'next': next_url,
        'count': pagination.total,
    })


@api.route('/posts/<int:id>')
def get_post(id):
    post = Post.query.get_or_404(id)
