@api.route('/posts/', methods=['POST'])
@permission_required(Permission.WRITE)
def new_post():
    post = Post.from_json(request.get_json(silent=True) or {})
    post.author = g.current_user
    db.session.add(post)
    db.session.commit()
    return jsonify(post.to_json()), 201, {
        'Location': url_for('api.get_post', id=post.id, _external=True)
    }


@api.route('/posts/<int:id>', methods=['PUT'])
@permission_required(Permission.WRITE)
def edit_post(id):
    post = Post.query.get_or_404(id)
    if g.current_user != post.author and not g.current_user.is_administrator():
        return forbidden('Insufficient permissions')
    json_post = request.get_json(silent=True) or {}
    if 'body' in json_post:
        post.body = json_post['body']
    if 'category' in json_post:
        post.category = (json_post.get('category') or 'general').strip() or 'general'
    db.session.add(post)
