from flask import current_app, g, jsonify, request, url_for

from .. import db
from ..models import Comment, Permission, Post
from . import api
from .decorators import permission_required
from .errors import forbidden


def _comment_query(base_query):
    if g.current_user.can(Permission.MODERATE):
        return base_query
    return base_query.filter_by(disabled=False)


def _paginate(query, endpoint, **kwargs):
    page = request.args.get('page', 1, type=int)
    per_page = min(
        request.args.get(
            'per_page',
            current_app.config['FLASKY_COMMENTS_PER_PAGE'],
            type=int,
        ),
        100,
    )
    pagination = query.paginate(page, per_page=per_page, error_out=False)
    prev_url = None
    if pagination.has_prev:
        prev_url = url_for(
            endpoint, page=page - 1, per_page=per_page, _external=True, **kwargs)
    next_url = None
    if pagination.has_next:
        next_url = url_for(
            endpoint, page=page + 1, per_page=per_page, _external=True, **kwargs)
    return pagination, prev_url, next_url


@api.route('/comments/')
def get_comments():
    query = _comment_query(Comment.query.order_by(Comment.timestamp.desc()))
    pagination, prev_url, next_url = _paginate(query, 'api.get_comments')
    comments = pagination.items
    return jsonify({
        'comments': [comment.to_json() for comment in comments],
        'prev': prev_url,
        'next': next_url,
        'count': pagination.total,
    })


@api.route('/comments/<int:id>')
def get_comment(id):
    comment = Comment.query.get_or_404(id)
    if comment.disabled and not g.current_user.can(Permission.MODERATE):
        return forbidden('Comment is disabled')
    return jsonify(comment.to_json())


@api.route('/posts/<int:id>/comments/')
def get_post_comments(id):
    post = Post.query.get_or_404(id)
    query = _comment_query(post.comments.order_by(Comment.timestamp.asc()))
    pagination, prev_url, next_url = _paginate(
        query, 'api.get_post_comments', id=id)
    comments = pagination.items
    return jsonify({
        'comments': [comment.to_json() for comment in comments],
        'prev': prev_url,
        'next': next_url,
        'count': pagination.total,
    })


@api.route('/posts/<int:id>/comments/', methods=['POST'])
@permission_required(Permission.COMMENT)
def new_post_comment(id):
    post = Post.query.get_or_404(id)
    comment = Comment.from_json(request.get_json(silent=True) or {})
    comment.author = g.current_user
    comment.post = post
    db.session.add(comment)
    db.session.commit()
    return jsonify(comment.to_json()), 201, {
        'Location': url_for('api.get_comment', id=comment.id, _external=True)
    }


@api.route('/comments/<int:id>', methods=['PUT'])
@permission_required(Permission.COMMENT)
def edit_comment(id):
    comment = Comment.query.get_or_404(id)
    if g.current_user != comment.author and not g.current_user.is_administrator():
        return forbidden('Insufficient permissions')
    json_comment = request.get_json(silent=True) or {}
    if 'body' in json_comment:
        comment.body = json_comment['body']
    if 'disabled' in json_comment and g.current_user.can(Permission.MODERATE):
        comment.disabled = bool(json_comment['disabled'])
    db.session.add(comment)
    db.session.commit()
    return jsonify(comment.to_json())


@api.route('/comments/<int:id>', methods=['DELETE'])
@permission_required(Permission.COMMENT)
def delete_comment(id):
    comment = Comment.query.get_or_404(id)
    if g.current_user != comment.author and not g.current_user.can(
        Permission.MODERATE
    ):
        return forbidden('Insufficient permissions')
    db.session.delete(comment)
    db.session.commit()
    return '', 204

