/workspace/app/templates/user.html.content:
{% extends "base.html" %}

{% block title %}{{ user.username }} | Flasky{% endblock %}

{% block page_content %}
<section class="card">
    <h1>{{ user.username }}</h1>
    <p>{{ user.name or 'No real name provided' }}</p>
    <p>{{ user.location or 'No location provided' }}</p>
    <p>{{ user.about_me or 'No bio yet.' }}</p>
    <p class="muted">
        Member since {{ user.member_since.strftime('%Y-%m-%d') }}.
        Last seen {{ user.last_seen.strftime('%Y-%m-%d %H:%M') }}.
    </p>
    <p class="muted">
        {{ follower_count }} followers · {{ followed_count }} followed ·
        {{ user.posts.count() }} posts
    </p>
    {% if current_user.is_authenticated %}
    <div class="actions">
        {% if current_user == user %}
        <a href="{{ url_for('main.edit_profile') }}">Edit Profile</a>
        {% elif current_user.is_following(user) %}
        <a href="{{ url_for('main.unfollow', username=user.username) }}">Unfollow</a>
        {% else %}
        <a href="{{ url_for('main.follow', username=user.username) }}">Follow</a>
        {% endif %}
        <a href="{{ url_for('main.followers', username=user.username) }}">Followers</a>
        <a href="{{ url_for('main.followed_by', username=user.username) }}">Following</a>
        {% if current_user.can(Permission.ADMIN) %}
        <a href="{{ url_for('main.edit_profile_admin', id=user.id) }}">Admin Edit</a>
        {% endif %}
    </div>
    {% endif %}
</section>

<section>
    <h2>Posts by {{ user.username }}</h2>
    {% include "_posts.html" %}
</section>
{% endblock %}

/workspace/app/templates/_posts.html.content:
{% for post in posts %}
<article class="card">
    <header class="card-header">
        <div>
            <a href="{{ url_for('main.user', username=post.author.username) }}">{{ post.author.username }}</a>
            <span class="muted">{{ post.timestamp.strftime('%Y-%m-%d %H:%M') }}</span>
        </div>
        <div class="muted">Category: {{ post.category or 'general' }}</div>
    </header>
    <div class="card-body">
        {% if post.body_html %}
        {{ post.body_html|safe }}
        {% else %}
        <p>{{ post.body }}</p>
        {% endif %}
    </div>
    <footer class="card-footer">
        <a href="{{ url_for('main.post', id=post.id) }}">Permalink</a>
        {% if current_user.is_authenticated and (current_user == post.author or current_user.can(Permission.ADMIN)) %}
        <a href="{{ url_for('main.edit', id=post.id) }}">Edit</a>
        <a href="{{ url_for('main.delete', id=post.id) }}">Delete</a>
        {% endif %}
    </footer>
</article>
{% else %}
<p class="muted">No posts yet.</p>
{% endfor %}

