/workspace/app/templates/moderate.html.content:
{% extends "base.html" %}

{% block title %}Moderate Comments | Flasky{% endblock %}

{% block page_content %}
<section>
    <h1>Comment Moderation</h1>
    {% for comment in comments %}
    <article class="card {% if comment.disabled %}is-disabled{% endif %}">
        <p>
            <a href="{{ url_for('main.user', username=comment.author.username) }}">{{ comment.author.username }}</a>
            on
            <a href="{{ url_for('main.post', id=comment.post.id) }}">post {{ comment.post.id }}</a>
        </p>
        <div>
            {% if comment.body_html %}
            {{ comment.body_html|safe }}
            {% else %}
            <p>{{ comment.body }}</p>
            {% endif %}
        </div>
        <p>
            {% if comment.disabled %}
            <a href="{{ url_for('main.moderate_enable', id=comment.id, page=page) }}">Enable</a>
            {% else %}
            <a href="{{ url_for('main.moderate_disable', id=comment.id, page=page) }}">Disable</a>
            {% endif %}
        </p>
    </article>
    {% else %}
    <p class="muted">No comments available.</p>
    {% endfor %}
</section>
{% endblock %}

/workspace/app/templates/_macros.html.content:
{% macro render_pagination(pagination, endpoint) -%}
<div class="pagination">
    {% if pagination.has_prev %}
    <a href="{{ url_for(endpoint, page=pagination.prev_num) }}">Previous</a>
    {% endif %}
    <span>Page {{ pagination.page }} of {{ pagination.pages or 1 }}</span>
    {% if pagination.has_next %}
    <a href="{{ url_for(endpoint, page=pagination.next_num) }}">Next</a>
    {% endif %}
</div>
{%- endmacro %}

