/workspace/app/static/styles.css.content:
body {
    margin: 0;
    font-family: "Georgia", serif;
    background: #f7f1e8;
    color: #2f241d;
}

a {
    color: #8a3b12;
    text-decoration: none;
}

a:hover {
    text-decoration: underline;
}

.container {
    max-width: 920px;
    margin: 0 auto;
    padding: 1rem;
}

.site-header {
    background: linear-gradient(135deg, #fef5de, #efd8b2);
    border-bottom: 1px solid #d3b895;
}

.nav {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
}

.nav nav {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
}

.brand {
    font-size: 1.3rem;
    font-weight: bold;
    letter-spacing: 0.04em;
}

.hero {
    padding: 1.5rem 0 0.5rem;
}

.muted {
    color: #6e5a4a;
}

.card {
    background: #fffdf8;
    border: 1px solid #d7c3aa;
    border-radius: 8px;
    padding: 1rem;
    margin: 1rem 0;
    box-shadow: 0 8px 24px rgba(90, 58, 33, 0.06);
}

.card-header,
.card-footer,
.toolbar,
.filters,
.actions,
.list-row {
    display: flex;
    justify-content: space-between;
    gap: 1rem;
    flex-wrap: wrap;
}

.card-footer {
    margin-top: 1rem;
}

.search-form {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.flashes {
    list-style: none;
    padding: 0;
}

.flashes li {
    background: #fff2c9;
    border: 1px solid #dfc98d;
    padding: 0.75rem;
    margin: 0.75rem 0;
    border-radius: 6px;
}

input,
textarea,
select,
button {
    width: 100%;
    max-width: 100%;
    padding: 0.6rem;
    border: 1px solid #cdb292;
    border-radius: 6px;
    box-sizing: border-box;
    font: inherit;
    background: white;
}

button,
input[type="submit"] {
    width: auto;
    cursor: pointer;
    background: #8a3b12;
    color: #fff7ef;
}

.auth-card {
    max-width: 36rem;
}

.is-disabled {
    opacity: 0.7;
}

@media (max-width: 700px) {
    .nav,
    .toolbar,
    .card-header,
    .card-footer {
        flex-direction: column;
        align-items: flex-start;
    }
}

