/workspace/app/templates/index.html.content:
{% extends "base.html" %}

{% block title %}Home | Flasky{% endblock %}

{% block page_content %}
<section class="hero">
    {% if current_user.is_authenticated %}
    <h1>Hello, {{ current_user.username }}!</h1>
    {% else %}
    <h1>Hello, Stranger!</h1>
    {% endif %}
    <p class="muted">A social blogging application built with Flask.</p>
</section>

<section class="toolbar">
    <form method="get" class="search-form">
        <input type="text" name="q" value="{{ q }}" placeholder="Search posts">
        <input type="text" name="category" value="{{ category }}" placeholder="Category">
        <button type="submit">Search</button>
    </form>
    {% if current_user.is_authenticated %}
    <div class="filters">
        <a href="{{ url_for('main.show_all') }}">All Posts</a>
        <a href="{{ url_for('main.show_followed') }}">Followed Posts</a>
        {% if show_followed %}
        <span class="muted">Showing followed posts</span>
        {% else %}
        <span class="muted">Showing all posts</span>
        {% endif %}
    </div>
    {% endif %}
</section>

{% if current_user.can(Permission.WRITE) %}
<section class="card">
    <h2>Write a post</h2>
    <form method="post">
        {{ form.hidden_tag() }}
        <p>{{ form.body.label }}<br>{{ form.body(rows=6) }}</p>
        <p>{{ form.category.label }}<br>{{ form.category() }}</p>
        <p>{{ form.submit() }}</p>
    </form>
</section>
{% endif %}

<section>
    <h2>Recent Posts</h2>
    {% include "_posts.html" %}
</section>
{% endblock %}

/workspace/app/templates/followers.html.content:
{% extends "base.html" %}

{% block title %}{{ title }} {{ user.username }} | Flasky{% endblock %}

{% block page_content %}
<section class="card">
    <h1>{{ title }} {{ user.username }}</h1>
    {% for follow in follows %}
    {% if endpoint == '.followers' %}
    {% set related = follow.follower %}
    {% else %}
    {% set related = follow.followed %}
    {% endif %}
    <div class="list-row">
        <a href="{{ url_for('main.user', username=related.username) }}">{{ related.username }}</a>
        <span class="muted">{{ follow.timestamp.strftime('%Y-%m-%d %H:%M') }}</span>
    </div>
    {% else %}
    <p class="muted">Nothing to show.</p>
    {% endfor %}
</section>
{% endblock %}

